Item.value:
var vpage=this.pageNum,vbox=this.getPageBox("Crop",vpage);

var vbei=app.response({cQuestion:"Border Effect Intensity:",cTitle:"Cloudy Border",cDefault:"0.5"});
if(vbei===null)exit;
vbei=Number(vbei);

var vwidth=app.response({cQuestion:"Border Width:",cTitle:"Cloudy Border",cDefault:"0.75"});
if(vwidth===null)exit;
vwidth=Number(vwidth);

this.addAnnot({
	page:vpage,
	type:"Square",
	rect:(new Matrix2D).fromRotated(this,vpage).transform([10,10,vbox[2]-10,vbox[1]-10]),
	strokeColor:color.red,
	fillColor:color.transparent,
	width:vwidth,
	borderEffectStyle:"C",
	borderEffectIntensity:vbei,
	author:"U355691",
	opacity:1,
	subject:"cloud"
});
